def main(employee: str, leave_type: str, date: str = None) -> dict:
	as_of = date or frappe.utils.today()
	balance = frappe.call(
		"hrms.hr.doctype.leave_application.leave_application.get_leave_balance_on",
		employee=employee,
		leave_type=leave_type,
		date=as_of,
	)
	return {"employee": employee, "leave_type": leave_type, "date": as_of, "balance": balance}
